BEGIN;
SET ROLE oo_target_owner;
SELECT pg_catalog.set_config('_oo.writer', 'apply-receipt', true);
ALTER TABLE _oo.apply_receipts DROP CONSTRAINT apply_receipts_segment_check;
ALTER TABLE _oo.apply_receipts ADD CONSTRAINT apply_receipts_segment_check CHECK (( (segment_count IS NULL AND segment_index IS NULL AND octet_length(segment_bitmap) = 0) OR (segment_count >= 1 AND segment_index >= 0 AND segment_index < segment_count AND octet_length(segment_bitmap) BETWEEN 1 AND 8192) )) NOT VALID;
COMMIT;
